# The 5 is aligned for the right hand and the 8 is below the left hand.
# I will use synchronized guarded motions to pick up both separated tiles efficiently.
def move_both(left_xyz, left_q, left_grip, right_xyz, right_q, right_grip, max_steps=18):
    global obs, steps_left, halted, motion_fault
    if halted or motion_fault or steps_left <= 0:
        return False
    initial = {arm: np.array(obs['state'][arm + '_ee_pose']) for arm in ['left', 'right']}
    targets = {'left': np.array(list(left_xyz) + list(left_q)), 'right': np.array(list(right_xyz) + list(right_q))}
    for arm in ['left', 'right']:
        targets[arm][3:] = targets[arm][3:] / np.linalg.norm(targets[arm][3:])
        if np.sum(initial[arm][3:] * targets[arm][3:]) < 0:
            targets[arm][3:] = -targets[arm][3:]
    for j in range(min(max_steps, steps_left)):
        alpha = min(1.0, (j + 1) / max(1, max_steps - 6))
        a = {'left_ee_joint_state': [left_grip], 'right_ee_joint_state': [right_grip]}
        for arm in ['left', 'right']:
            p = initial[arm] * (1-alpha) + targets[arm]*alpha
            p[3:] = p[3:] / np.linalg.norm(p[3:])
            a[arm + '_ee_pose'] = p
        obs, reward, terminated, truncated, info = step(a)
        steps_left -= 1
        halted = terminated or truncated or bool(info.get('success', False))
        for arm in ['left', 'right']:
            m = np.array(obs['state'][arm + '_ee_pose'])
            if np.linalg.norm(m[:3]-a[arm+'_ee_pose'][:3]) > 0.06 or 1-abs(float(np.sum(m[3:]*a[arm+'_ee_pose'][3:]))) > 0.03:
                motion_fault = True
        if halted or motion_fault:
            break
    for arm in ['left', 'right']:
        m = np.array(obs['state'][arm + '_ee_pose'])
        error = np.linalg.norm(m[:3]-targets[arm][:3])
        if error > 0.004 or 1-abs(float(np.sum(m[3:]*targets[arm][3:]))) > 0.001:
            motion_fault = True
        print(arm, 'error', error, 'pose', m)
    print('remaining', steps_left, 'fault', motion_fault, 'halted', halted)
    return not motion_fault
